import React, { useState, useMemo, useRef, useCallback, useEffect } from 'react';
import { FallLocationWarningFilters, FallWarningCurrentStatus } from '../../../models/FallLocationWarning';
import { useResponsive } from '../../../hooks/useResponsive';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './FallWarningFiltersBar.module.css';
import { Input, Select, SelectOption, DateRangeFilter, DEFAULT_LIST_PRESETS } from '@linm-soft-org/linm-web-common-components';

interface Props {
  filters:  FallLocationWarningFilters;
  onChange: (f: FallLocationWarningFilters) => void;
  onClear:  () => void;
}

const BASE_STATUS_OPTIONS: SelectOption[] = [
  { value: FallWarningCurrentStatus.NotFixed,   label: 'Chưa khắc phục' },
  { value: FallWarningCurrentStatus.InProgress, label: 'Đang khắc phục' },
  { value: FallWarningCurrentStatus.Fixed,      label: 'Đã khắc phục'   },
];

export const FallWarningFiltersBar: React.FC<Props> = ({ filters, onChange, onClear }) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);

  const { departmentOptions } = useFormOptions('fall-warning-list');

  const allStatusOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả trạng thái' }, ...BASE_STATUS_OPTIONS],
    [],
  );

  const allDeptOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả khoa' }, ...departmentOptions],
    [departmentOptions],
  );

  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.search)                   count++;
    if (filters.currentStatus)            count++;
    if (filters.departmentId)             count++;
    if (filters.fromDate || filters.toDate) count++;
    return count;
  }, [filters]);

  const hasActiveFilters = activeFilterCount > 0;

  const buttonRef = useRef<HTMLButtonElement>(null);
  const [dropdownStyle, setDropdownStyle] = useState<React.CSSProperties>({});

  const computeDropdownStyle = useCallback(() => {
    if (!buttonRef.current) return;
    const rect = buttonRef.current.getBoundingClientRect();
    const panelWidth = Math.min(300, window.innerWidth - 16);
    const centeredLeft = Math.max(8, (window.innerWidth - panelWidth) / 2);
    setDropdownStyle({ top: rect.bottom + 8, left: centeredLeft, width: panelWidth });
  }, []);

  const handleToggle = () => {
    if (!isExpanded) computeDropdownStyle();
    setIsExpanded((v) => !v);
  };
  const handleClose = () => setIsExpanded(false);

  useEffect(() => {
    if (!isExpanded) return;
    const close = () => setIsExpanded(false);
    window.addEventListener('scroll', close, { passive: true, capture: true });
    window.addEventListener('resize', close, { passive: true });
    return () => {
      window.removeEventListener('scroll', close, { capture: true });
      window.removeEventListener('resize', close);
    };
  }, [isExpanded]);

  // ── Mobile: toggle button + backdrop + dropdown panel ──────────────────────
  if (isMobile) {
    return (
      <>
        {isExpanded && (
          <div className={styles.filterBackdrop} onClick={handleClose} />
        )}
        <div className={styles.filterDropdownWrapper}>
          <button
            ref={buttonRef}
            className={styles.filterToggle}
            onClick={handleToggle}
            aria-expanded={isExpanded}
            aria-label="Bật / tắt bộ lọc"
            type="button"
          >
            <i className="fas fa-filter" />
            <span>Lọc</span>
            {activeFilterCount > 0 && (
              <span className={styles.filterBadge}>{activeFilterCount}</span>
            )}
            <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`} />
          </button>

          {isExpanded && (
            <div className={styles.mobileFilters} style={dropdownStyle}>
              <DateRangeFilter
                fromDate={filters.fromDate}
                toDate={filters.toDate}
                presets={DEFAULT_LIST_PRESETS}
                onChange={(val) => onChange({ ...filters, fromDate: val.fromDate, toDate: val.toDate })}
              />
              <Input
                placeholder="Tìm theo vị trí, mã..."
                value={filters.search ?? ''}
                onChange={(e) => onChange({ ...filters, search: e.target.value })}
                size="small"
              />
              <Select
                options={allStatusOptions}
                value={filters.currentStatus ?? ''}
                onChange={(e) =>
                  onChange({ ...filters, currentStatus: e.target.value as FallWarningCurrentStatus | '' })
                }
                size="small"
                fullWidth
              />
              <Select
                options={allDeptOptions}
                value={filters.departmentId ?? ''}
                onChange={(e) => onChange({ ...filters, departmentId: e.target.value })}
                size="small"
                fullWidth
              />
              {hasActiveFilters && (
                <button
                  className={styles.clearFiltersButton}
                  onClick={() => { onClear(); handleClose(); }}
                  type="button"
                >
                  <i className="fas fa-times-circle" />
                  <span>Xóa bộ lọc</span>
                </button>
              )}
            </div>
          )}
        </div>
      </>
    );
  }

  // ── Desktop: horizontal row ─────────────────────────────────────────────────
  return (
    <div className={styles.filters}>
      <DateRangeFilter
        fromDate={filters.fromDate}
        toDate={filters.toDate}
        presets={DEFAULT_LIST_PRESETS}
        onChange={(val) => onChange({ ...filters, fromDate: val.fromDate, toDate: val.toDate })}
      />
      <Input
        placeholder="Tìm theo vị trí, mã..."
        value={filters.search ?? ''}
        onChange={(e) => onChange({ ...filters, search: e.target.value })}
        size="small"
        className={styles.searchInput}
      />
      <Select
        options={allStatusOptions}
        value={filters.currentStatus ?? ''}
        onChange={(e) =>
          onChange({ ...filters, currentStatus: e.target.value as FallWarningCurrentStatus | '' })
        }
        size="small"
      />
      <Select
        options={allDeptOptions}
        value={filters.departmentId ?? ''}
        onChange={(e) => onChange({ ...filters, departmentId: e.target.value })}
        size="small"
      />
      {hasActiveFilters && (
        <button
          className={styles.clearFiltersButtonDesktop}
          onClick={onClear}
          type="button"
          title="Xóa bộ lọc"
        >
          <i className="fas fa-times-circle" />
          <span>Xóa bộ lọc</span>
        </button>
      )}
    </div>
  );
};

