import React, { useCallback, useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppDispatch } from '../../store/hooks';
import { addToast } from '../../store/slices/uiSlice';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { medicalIncidentService } from '../../services/medicalIncidents/medicalIncidentService';
import {
  MedicalIncident,
  MedicalIncidentFilters,
  MedicalIncidentStats,
  IncidentStatus,
  IncidentSeverity,
} from '../../models/MedicalIncident';
import styles from './ServiceMismatchReportPage.module.css';

// ─── Reusable filter bar ──────────────────────────────────────────────────────

import { StatsCard, StatsCardsGrid, TableCard, Pagination, DateRangeFilter, REPORT_PRESETS } from '@linm-soft-org/linm-web-common-components';
interface FilterState {
  search?:       string;
  status?:       IncidentStatus | '';
  severity?:     IncidentSeverity | '';
  departmentId?: string;
  dateFrom?:     string;
  dateTo?:       string;
}

const STATUS_OPTIONS = [
  { value: '', label: 'Tất cả trạng thái' },
  { value: IncidentStatus.Submitted,  label: 'Đã gửi' },
  { value: IncidentStatus.InAnalysis, label: 'Đang phân tích' },
  { value: IncidentStatus.Resolved,   label: 'Đã hoàn thành' },
  { value: IncidentStatus.Closed,     label: 'Đã đóng' },
];

const SEVERITY_OPTIONS = [
  { value: '', label: 'Tất cả mức độ' },
  { value: IncidentSeverity.Mild,   label: 'Nhẹ' },
  { value: IncidentSeverity.Medium, label: 'Trung bình' },
  { value: IncidentSeverity.Severe, label: 'Nghiêm trọng' },
];

// ─────────────────────────────────────────────────────────────────────────────

const PAGE_SIZE = 20;

const ServiceMismatchReportPage: React.FC = () => {
  const dispatch    = useAppDispatch();

  const [filters,   setFiltersState] = useState<FilterState>({});
  const [items,     setItems]        = useState<MedicalIncident[]>([]);
  const [total,     setTotal]        = useState(0);
  const [page,      setPage]         = useState(1);
  const [loading,   setLoading]      = useState(false);
  const showLoading = useMinLoadingTime(loading);
  const cancelRef   = useRef(false);

  // ── Stats: loaded ONCE from stats endpoint, never reloads on filter change ──
  const [stats, setStats]           = useState<MedicalIncidentStats | null>(null);
  const [statsLoading, setStatsLoading] = useState(true);
  const statsCancelRef = useRef(false);

  useEffect(() => {
    statsCancelRef.current = false;
    const t = setTimeout(async () => {
      try {
        const s = await medicalIncidentService.getStats({ isServiceMismatch: true });
        if (!statsCancelRef.current) { setStats(s); setStatsLoading(false); }
      } catch {
        if (!statsCancelRef.current) setStatsLoading(false);
      }
    }, 0);
    return () => { clearTimeout(t); statsCancelRef.current = true; };
  }, []);

  // ── List: reloads when filters/page change ─────────────────────────────────
  const load = useCallback(async (f: FilterState, p: number) => {
    cancelRef.current = false;
    setLoading(true);
    try {
      const apiFilters: MedicalIncidentFilters = {
        ...f,
        isServiceMismatch: true,
      };
      const result = await medicalIncidentService.getList(apiFilters, p, PAGE_SIZE);
      if (cancelRef.current) return;
      setItems(result.items);
      setTotal(result.total ?? 0);
    } catch {
      if (!cancelRef.current) dispatch(addToast({ type: 'error', message: 'Không thể tải danh sách sự cố nhầm dịch vụ' }));
    } finally {
      if (!cancelRef.current) setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    const t = setTimeout(() => load(filters, page), 0);
    return () => { clearTimeout(t); cancelRef.current = true; };
  }, [load, filters, page]);

  const handleFilter = (f: FilterState) => { setFiltersState(f); setPage(1); };
  const handleClear  = () => { setFiltersState({}); setPage(1); };

  const statusColor: Record<string, string> = {
    [IncidentStatus.Submitted]:  '#3b82f6',
    [IncidentStatus.InAnalysis]: '#f59e0b',
    [IncidentStatus.Resolved]:   '#10b981',
    [IncidentStatus.Closed]:     '#6b7280',
    [IncidentStatus.Draft]:      '#94a3b8',
  };

  const statusLabel: Record<string, string> = {
    [IncidentStatus.Draft]:      'Nháp',
    [IncidentStatus.Submitted]:  'Đã gửi',
    [IncidentStatus.InAnalysis]: 'Đang phân tích',
    [IncidentStatus.Resolved]:   'Đã hoàn thành',
    [IncidentStatus.Closed]:     'Đã đóng',
  };

  const showStatsLoading = statsLoading;

  return (
    <div className={styles.page}>
      {/* Page header */}
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-exchange-alt" /> Báo Cáo Sự Cố Nhầm Dịch Vụ
        </h1>
      </div>

      {/* Stats — from stats endpoint, loaded once, never changes on filter */}
      <StatsCardsGrid>
        <StatsCard label="Tổng sự cố nhầm DV"  value={stats?.total ?? 0}       icon="fas fa-exchange-alt"  variant="primary"   loading={showStatsLoading} />
        <StatsCard label="Đã gửi"              value={stats?.submitted ?? 0}   icon="fas fa-paper-plane"   variant="gray"      loading={showStatsLoading} />
        <StatsCard label="Đang phân tích"       value={stats?.inAnalysis ?? 0}  icon="fas fa-search"        variant="warning"   loading={showStatsLoading} />
        <StatsCard label="Đã hoàn thành"        value={(stats?.resolved ?? 0) + (stats?.closed ?? 0)} icon="fas fa-check-circle"  variant="success"   loading={showStatsLoading} />
      </StatsCardsGrid>

      {/* Table */}
      <TableCard
        header={
          <div className={styles.filterBar}>
            <input
              type="text"
              placeholder="Tìm theo tên bệnh nhân, mã sự cố..."
              value={filters.search ?? ''}
              onChange={(e) => handleFilter({ ...filters, search: e.target.value || undefined })}
              className={styles.searchInput}
            />
            <select
              value={filters.status ?? ''}
              onChange={(e) => handleFilter({ ...filters, status: (e.target.value as IncidentStatus) || undefined })}
              className={styles.select}
            >
              {STATUS_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
            </select>
            <select
              value={filters.severity ?? ''}
              onChange={(e) => handleFilter({ ...filters, severity: (e.target.value as IncidentSeverity) || undefined })}
              className={styles.select}
            >
              {SEVERITY_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
            </select>
            <DateRangeFilter
              fromDate={filters.dateFrom}
              toDate={filters.dateTo}
              presets={REPORT_PRESETS}
              onChange={(val) => handleFilter({ ...filters, dateFrom: val.fromDate, dateTo: val.toDate })}
            />
            {(filters.search || filters.status || filters.severity || filters.dateFrom || filters.dateTo) && (
              <button onClick={handleClear} className={styles.clearBtn}>
                <i className="fas fa-times" /> Xóa lọc
              </button>
            )}
          </div>
        }
        footer={
          total > PAGE_SIZE ? (
            <Pagination
              currentPage={page}
              totalPages={Math.ceil(total / PAGE_SIZE)}
              totalCount={total}
              pageSize={PAGE_SIZE}
              onPageChange={setPage}
            />
          ) : undefined
        }
      >
        {showLoading ? (
          <div className={styles.center}><i className="fas fa-spinner fa-spin" /> Đang tải...</div>
        ) : items.length === 0 ? (
          <div className={styles.center}>
            <i className="fas fa-inbox" style={{ fontSize: '2rem', display: 'block', marginBottom: 8 }} />
            Không có sự cố nhầm dịch vụ nào
          </div>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>Mã sự cố</th>
                  <th>Tên sự cố</th>
                  <th>Bệnh nhân</th>
                  <th>Khoa</th>
                  <th>Mức độ</th>
                  <th>Trạng thái</th>
                  <th>Ngày xảy ra</th>
                  <th>Người báo cáo</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr key={item.id}>
                    <td>
                      <Link className={styles.codeLink} to={scykRoutes.incidents.detail(item.id)}>
                        {item.idCode}
                      </Link>
                    </td>
                    <td style={{ maxWidth: 200 }}>{item.incidentName}</td>
                    <td>{item.patientName || '—'}</td>
                    <td>{item.departmentName || '—'}</td>
                    <td>{item.severity || '—'}</td>
                    <td>
                      <span style={{
                        padding: '2px 8px', borderRadius: 12,
                        background: (statusColor[item.status] ?? '#94a3b8') + '20',
                        color: statusColor[item.status] ?? '#94a3b8',
                        fontSize: '0.75rem', fontWeight: 600,
                      }}>
                        {statusLabel[item.status] ?? item.status}
                      </span>
                    </td>
                    <td>{item.occurredAt ? new Date(item.occurredAt).toLocaleDateString('vi-VN') : '—'}</td>
                    <td>{item.createdByName}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </TableCard>
    </div>
  );
};

export default ServiceMismatchReportPage;
