import React, { useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

/** Sync MemoryRouter with shell navigation (single-spa / browser URL). */
export const RouterSync: React.FC = () => {
  const navigate = useNavigate();
  const { pathname, search } = useLocation();

  useEffect(() => {
    const sync = () => {
      const next = window.location.pathname + window.location.search;
      const current = pathname + search;
      if (next !== current) navigate(next, { replace: true });
    };
    window.addEventListener('single-spa:routing-event', sync);
    window.addEventListener('popstate', sync);
    return () => {
      window.removeEventListener('single-spa:routing-event', sync);
      window.removeEventListener('popstate', sync);
    };
  }, [navigate, pathname, search]);

  return null;
};
